  if (player->cards != 2) {
    whichCard = CARD_YELLOW;
    pwVar3 = &team->teamStatsPtr->bookings;
    *pwVar3 = *pwVar3 + 1;
    return 0;
  }
  whichCard = CARD_SECOND_YELLOW;
  pTVar2 = team->teamStatsPtr;
